# build complete mapping including all-equal -> that value
def f(inp):
    h,w=inp.shape; hh_,hw_=h//2,w//2
    Q={'TL':inp[:hh_,:hw_],'TR':inp[:hh_,hw_:],'BL':inp[hh_:,:hw_],'BR':inp[hh_:,hw_:]}
    gc=Counter(inp.flatten().tolist())
    out=[]
    for i_ in range(hh_):
        r_=[]
        for j_ in range(hw_):
            vs=[int(Q[n][i_][j_]) for n in qs]; c=Counter(vs)
            v=tuple(sorted(vs))
            if v in tab: r_.append(tab[v])
            elif len(c)==1: r_.append(list(c)[0])   # all four same
            else:
                ones=[x for x,n in c.items() if n==1]
                if ones: r_.append(min(ones,key=lambda x:gc[x]))
                else: r_.append(max(c.most_common(),key=lambda kv:-kv[1])[0])
        out.append(r_)
    return out
